# 编辑操作：Match / Delete / Replace / Insert
def edit_ops(a, b):
    if a == b:
        return ("Match", a, b, 0)
    if a == "-":
        return ("Insert", a, b, 1)
    if b == "-":
        return ("Delete", a, b, 1)
    return ("Replace", a, b, 1)

